import os
from typing import List, Dict, Any
import boto3
from botocore.exceptions import ClientError

def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    """
    Extract structured fields from an invoice using Amazon Textract.
    Returns a dictionary with vendor, date, total, and line_items.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    textract_client = boto3.client('textract', region_name='us-east-1')

    with open(file_path, 'rb') as document:
        image_bytes = document.read()

    try:
        response = textract_client.analyze_expense(
            Document={'Bytes': image_bytes}
        )
    except ClientError as e:
        raise RuntimeError(f"AWS Textract error: {e}")

    summary_fields = {}
    line_items = []

    for expense_doc in response.get('ExpenseDocuments', []):
        for summary_field in expense_doc.get('SummaryFields', []):
            field_type = summary_field.get('Type', {}).get('Text', '').lower()
            field_text = summary_field.get('ValueDetection', {}).get('Text', '')

            if 'vendor' in field_type or 'seller' in field_type:
                summary_fields['vendor'] = field_text
            elif 'date' in field_type:
                summary_fields['date'] = field_text
            elif 'total' in field_type or 'invoice_total' in field_type:
                summary_fields['total'] = field_text

        for line_item_group in expense_doc.get('LineItemGroups', []):
            for line_item in line_item_group.get('LineItems', []):
                item_fields = {}
                for expense_field in line_item.get('LineItemExpenseFields', []):
                    field_type = expense_field.get('Type', {}).get('Text', '').lower()
                    field_text = expense_field.get('ValueDetection', {}).get('Text', '')

                    if 'item' in field_type or 'description' in field_type:
                        item_fields['description'] = field_text
                    elif 'quantity' in field_type:
                        item_fields['quantity'] = field_text
                    elif 'unit_price' in field_type:
                        item_fields['unit_price'] = field_text
                    elif 'amount' in field_type or 'price' in field_type:
                        item_fields['amount'] = field_text

                if item_fields:
                    line_items.append(item_fields)

    result = {
        'vendor': summary_fields.get('vendor', ''),
        'date': summary_fields.get('date', ''),
        'total': summary_fields.get('total', ''),
        'line_items': line_items
    }

    return result
